@import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;800&display=swap');
:root{--color-primary:#1b4965;--color-primary-600:#143a52;--color-primary-rgb:27,73,101;--color-secondary:#0e7c7b;--color-accent:#d4a24c;--color-bg:#f7f5f0;--color-surface:#ffffff;--color-surface-2:#eeeae0;--color-border:#ded8c9;--color-text:#15202b;--color-text-muted:#4f5b67;--color-on-primary:#ffffff;--color-on-accent:#1a1207;--color-link:#1b4965;--color-hero-ink:#0b1b29;--color-success:#15803d;--color-warning:#b45309;--color-danger:#b91c1c;--color-info:#0369a1;--gradient-brand:linear-gradient(135deg,var(--color-primary),var(--color-secondary));--gradient-hero:radial-gradient(60% 50% at 15% 20%,color-mix(in srgb,var(--color-secondary) 22%,transparent),transparent),radial-gradient(50% 50% at 90% 10%,color-mix(in srgb,var(--color-accent) 22%,transparent),transparent),var(--color-bg);--gradient-text:linear-gradient(90deg,var(--color-accent),#f6dc9b,var(--color-accent));--gradient-glow:radial-gradient(circle,color-mix(in srgb,var(--color-accent) 70%,transparent),transparent 70%);--font-body:Vazirmatn,Tahoma,system-ui,sans-serif;--font-display:Vazirmatn,Tahoma,system-ui,sans-serif;--fs-xs:.8rem;--fs-sm:.9rem;--fs-md:1rem;--fs-lg:clamp(1.05rem,1rem+.3vw,1.2rem);--fs-xl:clamp(1.2rem,1.1rem+.5vw,1.45rem);--fs-2xl:clamp(1.45rem,1.2rem+1vw,1.9rem);--fs-3xl:clamp(1.8rem,1.3rem+2vw,2.7rem);--fs-4xl:clamp(2.1rem,1.5rem+2.8vw,3.6rem);--fs-5xl:clamp(2.3rem,1.5rem+4vw,4.6rem);--lh-tight:1.25;--lh-normal:1.8;--fw-regular:400;--fw-medium:500;--fw-bold:800;--section-y:clamp(64px,9vw,120px);--radius-sm:8px;--radius-md:14px;--radius-lg:22px;--radius-xl:32px;--radius-full:999px;--shadow-sm:0 2px 8px rgba(11,27,41,.06);--shadow-md:0 8px 24px rgba(11,27,41,.14);--shadow-lg:0 24px 60px rgba(11,27,41,.22);--shadow-glow:0 8px 30px color-mix(in srgb,var(--color-primary) 40%,transparent);--blur-glass:16px;--container-max:1240px;--ease-out:cubic-bezier(.22,1,.36,1);--ease-spring:cubic-bezier(.34,1.56,.64,1);--dur-fast:180ms;--dur-base:360ms;--dur-slow:700ms;--stagger:90ms;--space-1:4px;--space-2:8px;--space-3:12px;--space-4:16px;--space-5:20px;--space-6:24px;--space-7:32px;--space-8:40px;--space-9:48px;--space-10:64px;--space-11:80px;--space-12:96px}
@media (prefers-color-scheme: dark){:root{--color-primary:#2a77a0;--color-primary-600:#1f5f82;--color-primary-rgb:42,119,160;--color-bg:#0d1620;--color-surface:#142230;--color-surface-2:#101d2a;--color-border:#27405a;--color-text:#eef2f6;--color-text-muted:#a9b6c3;--color-link:#8fc9ea;--color-warning:#f0b44c}}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:var(--color-bg);color:var(--color-text);font-family:var(--font-body)}
.gt{background:var(--gradient-text);background-size:200% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:site-gt 6s linear infinite}
.btn-shine::after{content:'';position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.4) 50%,transparent 70%);transform:translateX(-130%);transition:transform 800ms var(--ease-out);pointer-events:none}.btn-shine:hover::after{transform:translateX(130%)}
.pcard:hover .pzoom{transform:scale(1.08)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:'';width:10px;height:10px;border-inline-end:2px solid var(--color-link);border-bottom:2px solid var(--color-link);transform:rotate(45deg);transition:transform var(--dur-base) var(--ease-out);flex:none}.faq[open] summary::after{transform:rotate(-135deg)}.faq[open]{border-color:var(--color-link)}
.field:focus{outline:none;border-color:var(--color-link);box-shadow:0 0 0 4px color-mix(in srgb,var(--color-link) 25%,transparent)}
a:focus-visible,button:focus-visible,summary:focus-visible,select:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--color-accent);outline-offset:3px}
@keyframes site-s3{0%{opacity:0;visibility:hidden}5%{opacity:1;visibility:visible}33%{opacity:1;visibility:visible}38%{opacity:0;visibility:hidden}100%{opacity:0;visibility:hidden}}
@keyframes site-s4{0%{opacity:0;visibility:hidden}4%{opacity:1;visibility:visible}25%{opacity:1;visibility:visible}29%{opacity:0;visibility:hidden}100%{opacity:0;visibility:hidden}}
@keyframes site-kb{from{transform:scale(1)}to{transform:scale(1.14)}}
@keyframes site-prog{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes site-marquee{to{transform:translateX(50%)}}
@keyframes site-grad{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
@keyframes site-gt{to{background-position:200% center}}
@supports (animation-timeline: view()){.reveal{animation:pb-fade-in-up both linear;animation-timeline:view();animation-range:entry 0% cover 30%}}
@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}}
@media print{*{animation:none!important;transition:none!important}}
